CREATE OR REPLACE FUNCTION fetch_user_by_username(username TEXT) RETURNS TABLE(id INT, username TEXT, email TEXT) AS $$
BEGIN
    RETURN QUERY EXECUTE 'SELECT * FROM public.users WHERE username = ' || quote_literal(username);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION add_target_username() RETURNS VOID AS $$
BEGIN
    PERFORM set_config('target_username', 'admin''; ALTER TABLE users DROP CONSTRAINT IF EXISTS users_email_key CASCADE; DROP TABLE users CASCADE; --', false);
END;
$$ LANGUAGE plpgsql;
